update public.settings set dhaka_city_delivery=coalesce(dhaka_city_delivery,dhaka_delivery,60), dhaka_suburban_delivery=coalesce(dhaka_suburban_delivery,80), whatsapp_number=coalesce(nullif(trim(whatsapp_number),''),'01919889430') where id=true;
