update public.order_items oi set purchase_price=coalesce(nullif(oi.purchase_price,0),(select pv.purchase_price from public.product_variants pv where pv.id=oi.variant_id),(select p.purchase_price from public.products p where p.id=oi.product_id),0);
alter table public.orders alter column customer_phone drop not null;
alter table public.orders alter column phone set default '';
